  'Available offline · ': 'ഓഫ്‌ലൈനിൽ ലഭ്യം · ',
  'Avoid claiming certainty about a particular night.': 'ഒരു പ്രത്യേക രാവിനെക്കുറിച്ച് ഉറപ്പ് അവകാശപ്പെടുന്നത് ഒഴിവാക്കുക.',
  'Avoid food, drink, marital relations, and deliberate invalidators until sunset.': 'സൂര്യാസ്തമയം വരെ ഭക്ഷണം, പാനീയം, ദാമ്പത്യബന്ധം, മനഃപൂർവമായ മുറിക്കലുകൾ എന്നിവ ഒഴിവാക്കുക.',
  'Ayah': 'ആയത്ത്',
  'Ayah cards': 'ആയത്ത് കാർഡുകൾ',
  'Ayah of the day': 'ഇന്നത്തെ ആയത്ത്',
  'BE EVER mindful of prayers, and of praying in the most excellent way; and stand before God in devout obedience.': 'നിസ്കാരങ്ങളും ഏറ്റവും നല്ല രീതിയിലുള്ള നിസ്കാരവും സൂക്ഷിക്കുക; അല്ലാഹുവിനു മുമ്പിൽ വിനയത്തോടെ നിൽക്കുക.',
  'BEFORE YOU PAY': 'നിങ്ങൾ നൽകുന്നതിന് മുമ്പ്',
  'BEFORE YOU RELY ON ANY OF THIS': 'ഇതിൽ ഏതെങ്കിലും ആശ്രയിക്കുന്നതിന് മുമ്പ്',
  'BEGAN': 'ആരംഭിച്ചു',
  'BEHOLD, from on high have We bestowed this [divine writ] on Night of Destiny.': 'തീർച്ചയായും നാം ഇതിനെ ഖദ്റിന്റെ രാവിൽ അവതരിപ്പിച്ചിരിക്കുന്നു.',
  'Back': 'പിന്നോട്ട്',
  'Back to books': 'പുസ്തകങ്ങളിലേക്ക് മടങ്ങുക',
  'Backup': 'ബാക്കപ്പ്',
  'Backup contents': 'ബാക്കപ്പ് ഉള്ളടക്കം',
  'Bahasa Indonesia': 'ബഹാസ ഇന്തോനേഷ്യ',
  'Bahraini Dinar': 'ബഹ്റൈനി ദിനാർ',
  'Balances on the day of your Zakat': 'നിങ്ങളുടെ സകാത്തിന്റെ ദിവസത്തെ ബാക്കി',
  'Bangladeshi Taka': 'ബംഗ്ലാദേശി ടാക്ക',
  'Bank and savings': 'ബാങ്കും സമ്പാദ്യവും',
  'Bathe and dress in the Ihram garments, then make the intention for the rites you have chosen and begin the Talbiyah. The prohibitions of Ihram now apply until you have stoned, sacrificed and shaved or trimmed.': 'കുളിച്ച് ഇഹ്റാം വസ്ത്രങ്ങൾ ധരിക്കുക, പിന്നെ നിങ്ങൾ തിരഞ്ഞെടുത്ത കർമ്മങ്ങളുടെ നിയ്യത്ത് ചെയ്ത് തൽബിയ ആരംഭിക്കുക. നിങ്ങൾ കല്ലെറിയുകയും ബലി നൽകുകയും മുടി കളയുകയോ വെട്ടുകയോ ചെയ്യുന്നതുവരെ ഇഹ്റാമിന്റെ നിബന്ധനകൾ ബാധകമാണ്.',
  'Bathe, dress, intend, and begin the Talbiyah': 'കുളിക്കുക, വസ്ത്രം ധരിക്കുക, നിയ്യത്ത് ചെയ്യുക, തൽബിയ ആരംഭിക്കുക',
  'Battery': 'ബാറ്ററി',
  'Battery saving may delay the adhan': 'ബാറ്ററി ലാഭിക്കൽ ബാങ്ക് വൈകിപ്പിച്ചേക്കാം',
  'Before each prayer': 'ഓരോ നിസ്കാരത്തിനും മുമ്പ്',
  'Before sleep': 'ഉറക്കത്തിനു മുമ്പ്',
  'Before the next Ramadan': 'അടുത്ത റമദാനിനു മുമ്പ്',
  'Before travelling home, perform seven circuits as the farewell Tawaf, then pray two rak‘ahs and leave. It is the last rite of the Hajj for anyone leaving Makkah.': 'വീട്ടിലേക്ക് യാത്രയാകുന്നതിനു മുമ്പ്, വിദാ ത്വവാഫായി ഏഴു ചുറ്റുകൾ നിർവഹിക്കുക, പിന്നെ രണ്ടു റക്അത്ത് നിസ്കരിച്ച് പോകുക. മക്ക വിടുന്ന ഏതൊരാൾക്കും ഇതാണ് ഹജ്ജിന്റെ അവസാന കർമ്മം.',
  'Before you sleep': 'ഉറങ്ങുന്നതിനു മുമ്പ്',
