  'Coming soon': 'ഉടൻ വരുന്നു',
  'Commentary on the Quran, in the language you read it in. Tafsir is one scholar’s reading, not the text itself.': 'നിങ്ങൾ വായിക്കുന്ന ഭാഷയിലുള്ള ഖുർആൻ വ്യാഖ്യാനം. തഫ്സീർ ഒരു പണ്ഡിതന്റെ വായനയാണ്, വാചകം തന്നെയല്ല.',
