  'Days': 'ദിവസങ്ങൾ',
  'Days fasted in each month, oldest first.': 'ഓരോ മാസവും നോമ്പെടുത്ത ദിവസങ്ങൾ, ഏറ്റവും പഴയത് ആദ്യം.',
  'Days missed through hayd or nifas are made up one for one. There is no fidyah on them, because fidyah belongs to the one who cannot make the day up at all. A woman who can fast later fasts later.': 'ഹൈദ് അല്ലെങ്കിൽ നിഫാസ് കാരണം വിട്ടുപോയ ദിവസങ്ങൾ ഒന്നിനൊന്നായി ഖദാ ചെയ്യുന്നു. അവയിൽ ഫിദ്‌യയില്ല, കാരണം ഫിദ്‌യ ഒരിക്കലും ഖദാ ചെയ്യാൻ കഴിയാത്തവന്റേതാണ്. പിന്നീട് നോമ്പെടുക്കാൻ കഴിയുന്ന ഒരു സ്ത്രീ പിന്നീട് നോമ്പെടുക്കുന്നു.',
  'Days of Ramadan missed through menstruation or post-natal bleeding are made up before the next Ramadan, one day for each day. They do not need to be consecutive, and they may be spread through the year — but they are a debt, so most women keep a running count. This area records those days for you and keeps the scorecard honest as you settle them.': 'ആർത്തവം അല്ലെങ്കിൽ പ്രസവാനന്തര രക്തസ്രാവം കാരണം വിട്ടുപോയ റമദാൻ ദിവസങ്ങൾ അടുത്ത റമദാനിനു മുമ്പ്, ഓരോ ദിവസത്തിനും ഒരു ദിവസമായി ഖദാ ചെയ്യുന്നു. അവ തുടർച്ചയായിരിക്കണമെന്നില്ല, വർഷം മുഴുവൻ വിതരണം ചെയ്യാം — പക്ഷേ അവ ഒരു കടമാണ്, അതിനാൽ മിക്ക സ്ത്രീകളും നിലവിലെ കണക്ക് സൂക്ഷിക്കുന്നു. ഈ മേഖല നിങ്ങൾക്കായി ആ ദിവസങ്ങൾ രേഖപ്പെടുത്തുന്നു, നിങ്ങൾ അവ തീർക്കുമ്പോൾ കണക്ക് സത്യസന്ധമായി നിലനിർത്തുന്നു.',
