  'Download all languages': 'എല്ലാ ഭാഷകളും ഡൗൺലോഡ് ചെയ്യുക',
  'Download collection': 'ശേഖരം ഡൗൺലോഡ് ചെയ്യുക',
  'Download failed': 'ഡൗൺലോഡ് പരാജയപ്പെട്ടു',
  'Download for offline': 'ഓഫ്‌ലൈനിനായി ഡൗൺലോഡ് ചെയ്യുക',
  'Download this collection for offline reading': 'ഓഫ്‌ലൈനിൽ വായിക്കാൻ ഈ ശേഖരം ഡൗൺലോഡ് ചെയ്യുക',
  'Download this collection to read it without a connection.': 'കണക്ഷനില്ലാതെ വായിക്കാൻ ഈ ശേഖരം ഡൗൺലോഡ് ചെയ്യുക.',
  'Downloaded': 'ഡൗൺലോഡ് ചെയ്തു',
