  'If bleeding continues past what is usual for you, the commonly cited limits are fifteen days for hayd and forty for nifas. Beyond them, the bleeding is generally treated as istihadha: pray, fast, and speak to a scholar and a doctor. Neither of them will find the question unusual.': 'രക്തസ്രാവം നിങ്ങളുടെ സാധാരണയിലധികം നീണ്ടാൽ, സാധാരണ ഉദ്ധരിക്കപ്പെടുന്ന പരിധികൾ ഹൈദിന് പതിനഞ്ചു ദിവസവും നിഫാസിന് നാല്പതും ആണ്. അവയ്ക്കപ്പുറം, രക്തസ്രാവം പൊതുവെ ഇസ്തിഹാദയായി കണക്കാക്കുന്നു: നിസ്കരിക്കുക, നോമ്പെടുക്കുക, ഒരു പണ്ഡിതനോടും ഒരു ഡോക്ടറോടും സംസാരിക്കുക. രണ്ടുപേരും ഈ ചോദ്യത്തെ അസാധാരണമായി കാണില്ല.',
  'If bleeding stops before Fajr and the fast is intended that night, the fast stands. Ghusl is required before the prayer; it is not a condition of the fast itself. A woman may wake in a state that defers Fajr and still hold a valid fast.': 'സുബ്ഹിക്കു മുമ്പ് രക്തസ്രാവം നിന്നാൽ ആ രാത്രി നോമ്പ് നിയ്യത്ത് ചെയ്തിട്ടുണ്ടെങ്കിൽ, നോമ്പ് സാധുവാണ്. നിസ്കാരത്തിനു മുമ്പ് ഗുസ്ൽ നിർബന്ധമാണ്; അത് നോമ്പിന്റെതന്നെ നിബന്ധനയല്ല. സുബ്ഹി വൈകുന്ന അവസ്ഥയിൽ ഉണർന്നാലും ഒരു സ്ത്രീക്ക് സാധുവായ നോമ്പ് നിലനിർത്താം.',
  'If this changes, this page changes with it.': 'ഇത് മാറിയാൽ, ഈ പേജും അതിനൊപ്പം മാറുന്നു.',
  'If today was not fasted': 'ഇന്ന് നോമ്പെടുത്തില്ലെങ്കിൽ',
  'If you are not sure, leave it. The answer is firmer with it, but it is not required.': 'ഉറപ്പില്ലെങ്കിൽ അത് വിടുക. അതോടെ ഉത്തരം കൂടുതൽ ഉറപ്പാകും, പക്ഷേ അത് നിർബന്ധമല്ല.',
