  'Leave ‘Arafah after sunset — before dawn — and go to Muzdalifah, where you pray Maghrib and ‘Isha together and spend the night. Gather the pebbles for the stoning here, then leave for Mina before or around dawn.': 'സൂര്യാസ്തമയത്തിനുശേഷം — പുലരിക്കു മുമ്പ് — അറഫാത്ത് വിട്ട് മുസ്ദലിഫയിലേക്ക് പോകുക, അവിടെ മഗ്‌രിബും ഇശായും ഒരുമിച്ച് നിസ്കരിച്ച് രാത്രി ചെലവഴിക്കുക. കല്ലെറിയാനുള്ള കല്ലുകൾ ഇവിടെ ശേഖരിക്കുക, പിന്നെ പുലരിക്കു മുമ്പോ ഏകദേശം പുലരിക്കോ മിനായിലേക്ക് പുറപ്പെടുക.',
  'Left out: downloaded recitation audio, which lives as files on this device and can be downloaded again, and the backup password itself.': 'ഒഴിവാക്കിയവ: ഡൗൺലോഡ് ചെയ്ത ഓതൽ ഓഡിയോ, അത് ഈ ഉപകരണത്തിൽ ഫയലുകളായി നിലനിൽക്കുകയും വീണ്ടും ഡൗൺലോഡ് ചെയ്യാവുന്നതുമാണ്, കൂടാതെ ബാക്കപ്പ് രഹസ്യവാക്കുതന്നെ.',
