  'Men shave the head or trim the hair all over; a shave is preferable. Women cut a fingertip’s length from the ends of the hair. With this, the Umrah is complete and everything Ihram had forbidden becomes lawful again.': 'പുരുഷന്മാർ തല മുണ്ഡനം ചെയ്യുകയോ മുടി മുഴുവൻ വെട്ടുകയോ ചെയ്യുന്നു; മുണ്ഡനമാണ് ഉത്തമം. സ്ത്രീകൾ മുടിയുടെ അറ്റത്തുനിന്ന് ഒരു വിരലിന്റെ നീളം മുറിക്കുന്നു. ഇതോടെ ഉംറ പൂർത്തിയാകുന്നു, ഇഹ്റാം നിരോധിച്ചതെല്ലാം വീണ്ടും അനുവദനീയമാകുന്നു.',
