  'Names': 'നാമങ്ങൾ',
  'Narrated Anas bin Malik:The Prophet (ﷺ) said, "Take Suhur as there is a blessing in it': 'അനസ് ബിൻ മാലിക് നിവേദനം: നബി ﷺ പറഞ്ഞു, «അത്താഴം കഴിക്കുക, അതിൽ ബർക്കത്തുണ്ട്',
  'Narrated Talha bin `Abdullah bin `Auf:I offered the funeral prayer behind Ibn `Abbas and he recited Al-Fatiha and said, "You should know that it (i.e. recitation of Al-Fatiha) is the tradition of the Prophet Muhammad (ﷺ)': 'ത്വൽഹ ബിൻ അബ്ദുല്ലാഹ് ബിൻ ഔഫ് നിവേദനം: ഞാൻ ഇബ്നു അബ്ബാസിന്റെ പിന്നിൽ ജനാസ നിസ്കരിച്ചു, അദ്ദേഹം അൽഫാതിഹ ഓതുകയും പറയുകയും ചെയ്തു, «ഇത് (അൽഫാതിഹ ഓതൽ) നബി മുഹമ്മദ് ﷺ യുടെ ചര്യയാണെന്ന് നിങ്ങൾ അറിയണം',
  'Narrator': 'നിവേദകൻ',
  'Naskh': 'നസ്ഖ്',
  'Natural bleeding that comes to a woman at its known time, without a cause such as injury or illness. Commonly cited limits are a minimum of three days and a maximum of fifteen, with at least fifteen days of purity between two cycles. Anything outside that pattern is usually treated as istihadha, and the details belong with a scholar.': 'ഒരു സ്ത്രീക്ക് അതിന്റെ അറിയപ്പെടുന്ന സമയത്ത് വരുന്ന സ്വാഭാവിക രക്തസ്രാവം, മുറിവോ രോഗമോ പോലുള്ള കാരണമില്ലാതെ. സാധാരണ ഉദ്ധരിക്കപ്പെടുന്ന പരിധികൾ കുറഞ്ഞത് മൂന്നു ദിവസവും കൂടിയത് പതിനഞ്ചും, രണ്ടു ചക്രങ്ങൾക്കിടയിൽ ചുരുങ്ങിയത് പതിനഞ്ചു ദിവസത്തെ ശുദ്ധിയും. ആ ക്രമത്തിനു പുറത്തുള്ളതെന്തും സാധാരണയായി ഇസ്തിഹാദയായി കണക്കാക്കുന്നു, വിശദാംശങ്ങൾ ഒരു പണ്ഡിതന്റെ അടുത്താണ്.',
