  'Open system settings': 'സിസ്റ്റം ക്രമീകരണങ്ങൾ തുറക്കുക',
  'Open the Android battery settings': 'ആൻഡ്രോയ്ഡ് ബാറ്ററി ക്രമീകരണങ്ങൾ തുറക്കുക',
