  'Open the audio player': 'ഓഡിയോ പ്ലെയർ തുറക്കുക',
  'Open the full reflection': 'പൂർണ്ണ ചിന്ത തുറക്കുക',
  'Open the prophets catalogue': 'പ്രവാചകന്മാരുടെ കാറ്റലോഗ് തുറക്കുക',
  'Open this page by choosing an item from the list before it.': 'ഇതിനു മുമ്പുള്ള പട്ടികയിൽ നിന്ന് ഒരു ഇനം തിരഞ്ഞെടുത്ത് ഈ പേജ് തുറക്കുക.',
  'Open to you': 'നിങ്ങൾക്ക് തുറന്നിരിക്കുന്നു',
  'Open to you without question — no school disputes it. Put a reciter on and let the day be filled with the sound of it. Listening is not a lesser substitute for reciting; it is its own worship, and these are often the days a woman listens most.': 'സംശയമില്ലാതെ നിങ്ങൾക്ക് തുറന്നിരിക്കുന്നു — ഒരു മദ്‌ഹബും അതിനെ എതിർക്കുന്നില്ല. ഒരു ഖാരിയെ ഇടുക, ആ ശബ്ദം ദിവസം നിറയട്ടെ. ഓതുന്നതിനുള്ള ഒരു തരംതാണ പകരക്കാരനല്ല കേൾവി; അത് അതിന്റേതായ ഒരു ആരാധനയാണ്, ഒരു സ്ത്രീ ഏറ്റവും കൂടുതൽ കേൾക്കുന്ന ദിവസങ്ങളാണിവ.',
  'Open verse actions to add a reflection.': 'ഒരു ചിന്ത ചേർക്കാൻ ആയത്ത് പ്രവർത്തനങ്ങൾ തുറക്കുക.',
  'Opening…': 'തുറക്കുന്നു…',
  'Opens a screen': 'ഒരു സ്ക്രീൻ തുറക്കുന്നു',
  'Optional': 'ഐച്ഛികം',
  'Optional — anything that helps us find it.': 'ഐച്ഛികം — അത് കണ്ടെത്താൻ സഹായിക്കുന്ന എന്തും.',
  'Optional. Nothing is downloaded until you finish setting up.': 'ഐച്ഛികം. സജ്ജീകരണം പൂർത്തിയാക്കുന്നതുവരെ ഒന്നും ഡൗൺലോഡ് ചെയ്യുന്നില്ല.',
  'Or an unscented anti-chafe balm in a stick': 'അല്ലെങ്കിൽ സുഗന്ധമില്ലാത്ത ആന്റി-ചേഫ് ബാം ഒരു സ്റ്റിക്കിൽ',
  'Or enter coordinates': 'അല്ലെങ്കിൽ നിർദ്ദേശാങ്കങ്ങൾ നൽകുക',
  'Or paste one instead': 'അല്ലെങ്കിൽ പകരം ഒന്ന് ഒട്ടിക്കുക',
  'Other': 'മറ്റുള്ളവ',
  'Other assets': 'മറ്റ് ആസ്തികൾ',
  'Other translations and commentary': 'മറ്റ് വിവർത്തനങ്ങളും വ്യാഖ്യാനങ്ങളും',
