  'PIN': 'പിൻ',
  'PIN saved, lock is off': 'പിൻ സംരക്ഷിച്ചു, പൂട്ട് ഓഫാണ്',
  'PLAN & NEARBY': 'പദ്ധതിയും സമീപവും',
