  'Page number': 'പേജ് നമ്പർ',
  'Page {n}': 'പേജ് {n}',
  'Page {p} marked as read': 'പേജ് {p} വായിച്ചതായി അടയാളപ്പെടുത്തി',
  'Page {p} · saved locally': 'പേജ് {p} · പ്രാദേശികമായി സംരക്ഷിച്ചു',
