  'Quran': 'ഖുർആൻ',
  'Quran 2:222': 'ഖുർആൻ 2:222',
  'Quran 2:222 — “And they ask you about menstruation…”': 'ഖുർആൻ 2:222 — «ആർത്തവത്തെക്കുറിച്ച് അവർ നിന്നോട് ചോദിക്കുന്നു…»',
  'Quran Audio': 'ഖുർആൻ ഓഡിയോ',
  'Quran TV and Sunnah TV play right here, from the broadcaster’s own stream. The other channels open outside this app, because carrying them here would need rights the app does not hold.': 'ഖുർആൻ ടിവിയും സുന്ന ടിവിയും പ്രക്ഷേപകന്റെ സ്വന്തം സ്ട്രീമിൽ നിന്ന് ഇവിടെത്തന്നെ പ്ലേ ചെയ്യുന്നു. മറ്റ് ചാനലുകൾ ഈ ആപ്പിന് പുറത്ത് തുറക്കുന്നു, കാരണം അവ ഇവിടെ കൊണ്ടുവരാൻ ആപ്പിനില്ലാത്ത അവകാശങ്ങൾ വേണ്ടിവരും.',
  'Quran Topics': 'ഖുർആൻ വിഷയങ്ങൾ',
  'Quran Vocabulary': 'ഖുർആൻ പദാവലി',
  'Quran audio': 'ഖുർആൻ ഓഡിയോ',
  'Quran cache {u} MB · limit {l} MB · total limit {t} MB': 'ഖുർആൻ കാഷെ {u} MB · പരിധി {l} MB · ആകെ പരിധി {t} MB',
  'Quran notes': 'ഖുർആൻ കുറിപ്പുകൾ',
  'Quran preparation stopped because live data could not be reached.': 'തത്സമയ ഡാറ്റയിൽ എത്താൻ കഴിയാത്തതിനാൽ ഖുർആൻ തയ്യാറാക്കൽ നിർത്തി.',
  'Quran reading': 'ഖുർആൻ വായന',
  'Quran reminder': 'ഖുർആൻ ഓർമ്മപ്പെടുത്തൽ',
  'Quran search': 'ഖുർആൻ തിരയൽ',
  'Quran study tools': 'ഖുർആൻ പഠന ഉപകരണങ്ങൾ',
  'Quran text, hadith, the Names and the supplications come from the sources named in the app. Rulings and guidance are summarised for learning; for a matter that affects your worship or your obligations, ask a qualified scholar. This app is not a source of legal or religious authority.': 'ഖുർആൻ വാചകം, ഹദീസ്, നാമങ്ങൾ, ദുആകൾ എന്നിവ ആപ്പിൽ പേരുനൽകിയ സ്രോതസ്സുകളിൽ നിന്നാണ് വരുന്നത്. വിധികളും മാർഗനിർദ്ദേശങ്ങളും പഠനത്തിനായി സംഗ്രഹിച്ചിരിക്കുന്നു; നിങ്ങളുടെ ആരാധനയെയോ ബാധ്യതകളെയോ ബാധിക്കുന്ന ഒരു കാര്യത്തിന്, യോഗ്യതയുള്ള ഒരു പണ്ഡിതനോട് ചോദിക്കുക. ഈ ആപ്പ് നിയമപരമോ മതപരമോ ആയ ഒരു അധികാര സ്രോതസ്സല്ല.',
  'Quran text, prayer times, hadith, the Names, supplications and the countdown to Hajj come from api.islamicdata.uz. Recitation audio comes from cdn.islamic.network. The adhan recordings you choose are downloaded from audio.islamicdata.uz. Gold and silver prices used by the Zakat calculator come from misc.islamicdata.uz. Each of these receives the request needed to answer it and nothing about you.': 'ഖുർആൻ വാചകം, നിസ്കാര സമയങ്ങൾ, ഹദീസ്, നാമങ്ങൾ, ദുആകൾ, ഹജ്ജിനുള്ള കൗണ്ട്ഡൗൺ എന്നിവ api.islamicdata.uz-ൽ നിന്നാണ് വരുന്നത്. ഓതൽ ഓഡിയോ cdn.islamic.network-ൽ നിന്നാണ് വരുന്നത്. നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന ബാങ്ക് റെക്കോർഡിംഗുകൾ audio.islamicdata.uz-ൽ നിന്നാണ് ഡൗൺലോഡ് ചെയ്യുന്നത്. സകാത്ത് കാൽക്കുലേറ്റർ ഉപയോഗിക്കുന്ന സ്വർണ്ണ-വെള്ളി വിലകൾ misc.islamicdata.uz-ൽ നിന്നാണ്. ഇവയോരോന്നിനും അതിന് ഉത്തരം നൽകാൻ ആവശ്യമായ അഭ്യർത്ഥന മാത്രം ലഭിക്കുന്നു, നിങ്ങളെക്കുറിച്ച് ഒന്നും ലഭിക്കുന്നില്ല.',
