  'Recitation source': 'ഓതലിന്റെ സ്രോതസ്സ്',
  'Recitation stays the Arabic Qur’an. This adds a voice in your own language underneath it.': 'ഓതൽ അറബി ഖുർആൻ തന്നെയാണ്. ഇത് അതിനു കീഴെ നിങ്ങളുടെ സ്വന്തം ഭാഷയിൽ ഒരു ശബ്ദം ചേർക്കുന്നു.',
  'Recitation streams live from attributed public sources. Playback, recents and playlists stay on this device.': 'ഓതൽ അവലംബമുള്ള പൊതു സ്രോതസ്സുകളിൽ നിന്ന് തത്സമയം സ്ട്രീം ചെയ്യുന്നു. പ്ലേബാക്ക്, സമീപകാലവ, പ്ലേലിസ്റ്റുകൾ എന്നിവ ഈ ഉപകരണത്തിൽ നിലനിൽക്കുന്നു.',
