  'Recitations': 'ഓതലുകൾ',
  'Recite and reflect on the Qur’an.': 'ഖുർആൻ ഓതുകയും അതിൽ ചിന്തിക്കുകയും ചെയ്യുക.',
  'Recite the reported dua of istikhara, naming the matter.': 'കാര്യം പേരെടുത്തുപറഞ്ഞ്, ഇസ്തിഖാറയുടെ റിപ്പോർട്ട് ചെയ്യപ്പെട്ട ദുആ ഓതുക.',
  'Recite the takbir on the way.': 'വഴിയിൽ തക്ബീർ ചൊല്ലുക.',
  'Recite with attentiveness rather than haste.': 'ധൃതിക്കുപകരം ശ്രദ്ധയോടെ ഓതുക.',
