  'Remove this saved round': 'ഈ സംരക്ഷിച്ച തവണ നീക്കം ചെയ്യുക',
  'Removes every notification from this list. Your reminders stay switched on and keep being sent.': 'ഈ പട്ടികയിൽ നിന്ന് എല്ലാ അറിയിപ്പുകളും നീക്കം ചെയ്യുന്നു. നിങ്ങളുടെ ഓർമ്മപ്പെടുത്തലുകൾ ഓണായി തുടരുകയും അയയ്ക്കപ്പെടുകയും ചെയ്യുന്നു.',
  'Removes every sunnah prayer you have marked. Your five daily prayers are kept in their own record and are not touched.': 'നിങ്ങൾ അടയാളപ്പെടുത്തിയ എല്ലാ സുന്നത്ത് നിസ്കാരങ്ങളും നീക്കം ചെയ്യുന്നു. നിങ്ങളുടെ അഞ്ചു നിസ്കാരങ്ങൾ അവയുടെ സ്വന്തം രേഖയിൽ സൂക്ഷിക്കുന്നു, അവയെ സ്പർശിക്കുന്നില്ല.',
