  'Restores the Surah and the exact moment when the app opens, paused and ready.': 'ആപ്പ് തുറക്കുമ്പോൾ സൂറത്തും കൃത്യമായ നിമിഷവും പുനഃസ്ഥാപിക്കുന്നു, നിർത്തിയിരിക്കുന്ന നിലയിൽ തയ്യാറായി.',
