  'Return to Makkah for Tawaf al-Ifādah, seven circuits, followed by the Sa‘i if you have not already performed it for the Hajj. This Tawaf is the essential pillar: the Hajj is not complete without it.': 'ത്വവാഫുൽ ഇഫാദയ്ക്കായി മക്കയിലേക്ക് മടങ്ങുക, ഏഴു ചുറ്റുകൾ, ഹജ്ജിനായി നിങ്ങൾ ഇതിനകം നിർവഹിച്ചിട്ടില്ലെങ്കിൽ അതിനെത്തുടർന്ന് സഅ്‌യ്. ഈ ത്വവാഫാണ് അനിവാര്യമായ റുക്ന്: അതില്ലാതെ ഹജ്ജ് പൂർത്തിയാകുന്നില്ല.',
  'Reveal Arabic': 'അറബി വെളിപ്പെടുത്തുക',
  'Reveal Arabic verse': 'അറബി ആയത്ത് വെളിപ്പെടുത്തുക',
