  'Review frequent Quranic words': 'ഇടയ്ക്കിടെ വരുന്ന ഖുർആൻ പദങ്ങൾ പുനരവലോകനം ചെയ്യുക',
  'Right-to-left layout throughout the app': 'ആപ്പിലുടനീളം വലത്തുനിന്ന് ഇടത്തോട്ടുള്ള ക്രമീകരണം',
  'Rinse the mouth and nose.': 'വായയും മൂക്കും കഴുകുക.',
  'Rise and stand upright.': 'എഴുന്നേറ്റ് നിവർന്നു നിൽക്കുക.',
  'Rite-by-rite journeys, counters and the holy-site channels': 'കർമ്മംതോറുമുള്ള യാത്രകൾ, കൗണ്ടറുകൾ, വിശുദ്ധ സ്ഥല ചാനലുകൾ',
  'Root': 'മൂലം',
  'Rounds completed on this phrase': 'ഈ വാക്യത്തിൽ പൂർത്തിയാക്കിയ ചുറ്റുകൾ',
  'Rounds completed on this phrase: {n}': 'ഈ വാക്യത്തിൽ പൂർത്തിയാക്കിയ തവണകൾ: {n}',
  'Rub the body with the hand where the water can reach, and finish by washing the feet.': 'വെള്ളം എത്തുന്നിടത്ത് കൈകൊണ്ട് ശരീരം തടവുക, കാലുകൾ കഴുകി അവസാനിപ്പിക്കുക.',
  'Rub the hair gently so water reaches the scalp, then pour three handfuls over the head.': 'വെള്ളം തലയോട്ടിയിൽ എത്തുന്നവിധം മുടി പതുക്കെ തടവുക, പിന്നെ തലയിൽ മൂന്നു കൈനിറയെ വെള്ളം ഒഴിക്കുക.',
  'Russian': 'റഷ്യൻ',
  'SAVE CURRENT QUEUE': 'നിലവിലെ ക്യൂ സംരക്ഷിക്കുക',
  'SAVE QUEUE AS PLAYLIST': 'ക്യൂ പ്ലേലിസ്റ്റായി സംരക്ഷിക്കുക',
