  'STREAKS': 'തുടർച്ചകൾ',
  'SUHOOR': 'അത്താഴം',
  'SURAHS OPENED THIS WEEK': 'ഈ ആഴ്ച തുറന്ന സൂറത്തുകൾ',
  'Sadaqah': 'സദഖ',
  'Safety pins, plus a spare set': 'സേഫ്റ്റി പിന്നുകൾ, കൂടാതെ ഒരു സ്പെയർ സെറ്റ്',
  'Sahih': 'സ്വഹീഹ്',
  'Sahih International': 'Sahih International',
  'Sahih Muslim — the hadith of Umm Atiyya on the signs of purity': 'സ്വഹീഹ് മുസ്‌ലിം — ശുദ്ധിയുടെ അടയാളങ്ങളെക്കുറിച്ചുള്ള ഉമ്മു അത്വിയ്യയുടെ ഹദീസ്',
  'Sahih al-Bukhari and Muslim — “Do what the pilgrim does, except do not circumambulate the House”': 'സ്വഹീഹ് ബുഖാരിയും മുസ്‌ലിമും — «ഹാജി ചെയ്യുന്നത് ചെയ്യുക, എന്നാൽ വീടിനെ (കഅ്ബയെ) പ്രദക്ഷിണം ചെയ്യരുത്»',
  'Sahih al-Bukhari, Kitab al-Hayd — the hadith of Aisha on making up fasts, not prayers': 'സ്വഹീഹ് ബുഖാരി, കിത്താബുൽ ഹൈദ് — നിസ്കാരങ്ങളല്ല, നോമ്പുകൾ ഖദാ ചെയ്യുന്നതിനെക്കുറിച്ചുള്ള ആഇശയുടെ ഹദീസ്',
  'Said for': 'പറയുന്നത്',
  'Salah Tracker': 'നിസ്കാര ട്രാക്കർ',
  'Salah counts the prayers you mark on the Prayer screen. Reading counts the verses you mark in the reader and the Mushaf pages you open. Dhikr comes from the Tasbih counter, and hifz from every verse you rate in recall practice. The week is kept on this device only.': 'നിസ്കാര സ്ക്രീനിൽ നിങ്ങൾ അടയാളപ്പെടുത്തുന്ന നിസ്കാരങ്ങളാണ് നിസ്കാരം എണ്ണുന്നത്. റീഡറിൽ നിങ്ങൾ അടയാളപ്പെടുത്തുന്ന ആയത്തുകളും നിങ്ങൾ തുറക്കുന്ന മുസ്ഹഫ് പേജുകളുമാണ് വായന എണ്ണുന്നത്. ദിക്‌ർ തസ്ബീഹ് കൗണ്ടറിൽ നിന്നും, ഹിഫ്സ് ഓർമ്മ പരിശീലനത്തിൽ നിങ്ങൾ റേറ്റ് ചെയ്യുന്ന ഓരോ ആയത്തിൽ നിന്നും വരുന്നു. ആഴ്ച ഈ ഉപകരണത്തിൽ മാത്രം സൂക്ഷിക്കുന്നു.',
  'Salah counts the prayers you mark on the Prayer screen. Reading counts the verses you mark in the reader and the Mushaf pages you open. Dhikr comes from the Tasbih counter, and hifz from every verse you rate in recall practice. Thirty days are kept, on this device only, and nothing is uploaded.': 'നിസ്കാരം എന്നത് നിങ്ങൾ നിസ്കാര സ്ക്രീനിൽ അടയാളപ്പെടുത്തുന്ന നിസ്കാരങ്ങളെ എണ്ണുന്നു. വായന എന്നത് റീഡറിൽ നിങ്ങൾ അടയാളപ്പെടുത്തുന്ന ആയത്തുകളും തുറക്കുന്ന മുസ്ഹഫ് പേജുകളും. ദിക്‌ർ തസ്ബീഹ് കൗണ്ടറിൽ നിന്നും, ഹിഫ്ദ് ഓർമ്മ പരിശീലനത്തിൽ നിങ്ങൾ റേറ്റ് ചെയ്യുന്ന ഓരോ ആയത്തിൽ നിന്നും. മുപ്പതു ദിവസം ഈ ഉപകരണത്തിൽ മാത്രം സൂക്ഷിക്കുന്നു, ഒന്നും അപ്‌ലോഡ് ചെയ്യുന്നില്ല.',
  'Salat al-Janazah is a communal obligation and is performed standing, without bowing or prostration.': 'സലാത്തുൽ ജനാസ ഒരു സാമൂഹിക ബാധ്യതയാണ്, നിന്നുകൊണ്ടാണ് നിർവഹിക്കുന്നത്, റുകൂഉം സുജൂദും ഇല്ലാതെ.',
  'Sample unavailable': 'സാമ്പിൾ ലഭ്യമല്ല',
  'Sandals already broken in — never new ones for this trip': 'ഇതിനകം ഉപയോഗിച്ചുപഴകിയ ചെരിപ്പുകൾ — ഈ യാത്രയ്ക്ക് ഒരിക്കലും പുതിയവ വേണ്ട',
  'Sanitary products in the quantity you will actually need': 'നിങ്ങൾക്ക് യഥാർത്ഥത്തിൽ ആവശ്യമുള്ള അളവിൽ സാനിറ്ററി ഉത്പന്നങ്ങൾ',
