  'Saved. Reminders are scheduled in the installed app.': 'സംരക്ഷിച്ചു. ഇൻസ്റ്റാൾ ചെയ്ത ആപ്പിൽ ഓർമ്മപ്പെടുത്തലുകൾ ഷെഡ്യൂൾ ചെയ്യുന്നു.',
