  'Scheduling…': 'ഷെഡ്യൂൾ ചെയ്യുന്നു…',
  'Scheherazade': 'ഷെഹ്റസാദെ',
  'Scheherazade New': 'ഷെഹ്റസാദെ ന്യൂ',
  'Scholars differ on which of the two to measure against. The lower threshold brings more wealth into Zakat; take the choice to someone you trust.': 'ഏതിനോടാണ് അളക്കേണ്ടതെന്നതിൽ പണ്ഡിതന്മാർ വ്യത്യാസപ്പെട്ടിരിക്കുന്നു. താഴ്ന്ന പരിധി സകാത്തിലേക്ക് കൂടുതൽ സമ്പത്ത് കൊണ്ടുവരുന്നു; ഈ തിരഞ്ഞെടുപ്പ് നിങ്ങൾ വിശ്വസിക്കുന്ന ഒരാളുടെ അടുത്ത് കൊണ്ടുപോകുക.',
  'Scholars differ. Reciting from memory is widely permitted; touching the physical mushaf is not, since it requires purification. On screens and phones the question turns on whether a device counts as a mushaf — many contemporary scholars permit reading and reciting from a phone for that reason, while others advise limiting it to looking and listening. Follow the position of a scholar you trust, and keep the Quran close either way: listening to recitation is open to everyone, in every state.': 'പണ്ഡിതന്മാർക്ക് ഭിന്നാഭിപ്രായമുണ്ട്. മനഃപാഠം ഓതുന്നത് വ്യാപകമായി അനുവദനീയമാണ്; ഭൗതിക മുസ്ഹഫിൽ തൊടുന്നത് അല്ല, കാരണം അതിന് ശുദ്ധി ആവശ്യമാണ്. സ്ക്രീനുകളിലും ഫോണുകളിലും ചോദ്യം ഒരു ഉപകരണം മുസ്ഹഫായി കണക്കാക്കപ്പെടുന്നുണ്ടോ എന്നതാണ് — അതിനാലാണ് പല സമകാലിക പണ്ഡിതരും ഫോണിൽ നിന്ന് വായിക്കാനും ഓതാനും അനുവദിക്കുന്നത്, മറ്റുചിലർ അതിനെ നോട്ടത്തിനും കേൾവിക്കുമായി പരിമിതപ്പെടുത്താൻ ഉപദേശിക്കുമ്പോൾ. നിങ്ങൾ വിശ്വസിക്കുന്ന ഒരു പണ്ഡിതന്റെ നിലപാട് പിന്തുടരുക, ഏതായാലും ഖുർആനെ അടുത്തു നിർത്തുക: ഓതൽ കേൾക്കുന്നത് എല്ലാവർക്കും, ഏതവസ്ഥയിലും തുറന്നിരിക്കുന്നു.',
