  'System scheduling is available in the installed mobile app.': 'ഇൻസ്റ്റാൾ ചെയ്ത മൊബൈൽ ആപ്പിൽ സിസ്റ്റം ഷെഡ്യൂളിംഗ് ലഭ്യമാണ്.',
  'System tone': 'സിസ്റ്റം ശബ്ദം',
  'TAFSIR SOURCE': 'തഫ്സീർ സ്രോതസ്സ്',
  'THE DAY THAT WAS MISSED': 'വിട്ടുപോയ ദിവസം',
  'THE INTENTION, IN THE HEART AND ON THE TONGUE': 'നിയ്യത്ത്, ഹൃദയത്തിലും നാവിലും',
